touch.src/orders.py:
def create_order(items):
    total = sum(i['price'] * i['qty'] for i in items)
    return {'items': items, 'total': total, 'status': 'open'}

touch.src/discounts.py:
def apply_discount(total, code):
    if code == 'VIP':
        return round(total * 0.9, 2)
    return total

touch.src/shipping.py:
def shipping_cost(total, country):
    if country == 'DE':
        return 0 if total > 50 else 4.99
    return 9.99

touch.src/refunds.py:
def refund(order, amount):
    order['refunded'] = amount
    return order

touch.src/warehouse.py:
def reserve(item, qty, stock):
    stock[item] = stock.get(item, 0) - qty
    return stock

touch.src/archival.py:
def archive_order(order, archive):
    archive.append(order)
    return archive
